* engcall.asm: how the game calls the engine (step 8.5d). The engine runs in MMU task 1, the game in task 0; both see slot 0
* ($0000..$1FFF: stack, direct page, mailbox, this code) and the constant page, nothing else of one another. A call is
* therefore an ordinary C call whose arguments are on the shared stack, plus a task switch around it:
*
*   _Name   ldd #index / jmp __engcall      the game side stub (generated by tools/mkgame.py, in the core)
*   __engcall   saves the return address, pushes eng_back as the return address of the engine routine, switches to task 1
*               and jumps to _eng_entry, which calls the routine of the table (api.c) with the stack as the stub got it
*   eng_back    switches back to task 0 and returns to the game; D and X (the result) are untouched
*
* Pointers in the arguments must point into the shared stack (or into the data windows, which both tasks map alike): the
* wrappers of src/game/engapi.c copy strings and results through their own frame. Not reentrant, and the engine never calls
* the game back. _banktab (farcall.asm's table of loaded banks) lives here too: the bank loader (api.c) fills it.

        INCLUDE mailbox.inc

        SECTION shared
        EXPORT  __engcall
        EXPORT  _eng_idx
        EXPORT  _banktab
        EXPORT  _eng_tr
        EXPORT  _eng_tn
        IMPORT  _eng_entry
        IMPORT  _tins

__engcall
        stb     >_eng_idx               B = the routine's number
        lda     >_eng_tn                a ring of the last 64 routine numbers, for the harness
        ldx     #_eng_tr
        stb     a,x
        inca
        anda    #$3F
        sta     >_eng_tn
        puls    x                       the game's return address
        stx     >eng_ret
        ldx     #eng_back
        pshs    x                       the engine routine returns here
        lda     #1
        sta     >FC_TASK
        ora     >_tins                  (the timer's fast clock, when the sound runs: src/engine/snd.asm)
        sta     >$FF91                  task 1: the next instruction comes from the same shared slot 0
        jmp     >_eng_entry

eng_back
        clr     >FC_TASK
        pshs    a                       (the engine's result is in D)
        lda     >_tins
        sta     >$FF91                  task 0 (and the timer's clock)
        puls    a
        jmp     [eng_ret]

        ENDSECTION

        SECTION shared2
eng_ret         RMB     2
_eng_idx        RMB     1
_eng_tn         RMB     1
_eng_tr         RMB     64
_banktab        RMB     64              index = bank id - 1: the first of the bank's two blocks, 0 = not in memory
        ENDSECTION
